var wrapper = document.createElement('div');
wrapper.className = 'card Card--card--qJMOC Card--cardPadded--d1sUG Card--containerQuery--+S0OY hourly-tables-replacement';
wrapper.setAttribute('aria-label', 'Hourly Meteorological Data');
wrapper.style.marginBottom = '20px';

var header = document.createElement('header');
header.className = 'Card--cardHeader--AE3k1';
var heading = document.createElement('h2');
heading.className = 'Card--cardHeading--M6yBx Card--ctaTitle--nqpOJ';
heading.textContent = 'Hourly Meteorological Tables';
header.appendChild(heading);
wrapper.appendChild(header);

var content = document.createElement('div');
content.className = 'Card--content--IOayG';

var linkList = document.createElement('ul');
linkList.style.listStyle = 'none';
linkList.style.padding = '0';
linkList.style.margin = '0';

var links = [
  { label: 'Hourly Temperature & Dew Point', url: 'https://www.weather.gov/help-hourly-forecasts' },
  { label: 'Hourly Wind Speed & Direction', url: 'https://www.weather.gov/forecast-tools' },
  { label: 'Hourly Precipitation Probability', url: 'https://www.weather.gov/forecasts' },
  { label: 'Hourly Pressure & Humidity', url: 'https://www.weather.gov/data/gisdmr.php' },
  { label: 'Hourly UV Index & Solar Radiation', url: 'https://www.weather.gov/safety/sunburn' }
];

links.forEach(function(linkData) {
  var li = document.createElement('li');
  li.style.padding = '12px 0';
  li.style.borderBottom = '1px solid #e0e0e0';

  var a = document.createElement('a');
  a.href = linkData.url;
  a.target = '_blank';
  a.rel = 'noopener noreferrer';
  a.style.textDecoration = 'none';
  a.style.color = '#0066cc';
  a.style.fontSize = '16px';
  a.style.fontWeight = '500';
  a.style.display = 'block';

  var icon = document.createElement('span');
  icon.textContent = '📊 ';
  a.appendChild(icon);

  var text = document.createElement('span');
  text.textContent = linkData.label;
  a.appendChild(text);

  li.appendChild(a);
  linkList.appendChild(li);
});

content.appendChild(linkList);

var sourceNote = document.createElement('p');
sourceNote.style.marginTop = '15px';
sourceNote.style.fontSize = '13px';
sourceNote.style.color = '#888';
sourceNote.textContent = 'Data sourced from NOAA National Weather Service. Tables update every hour.';
content.appendChild(sourceNote);

wrapper.appendChild(content);

var footer = document.createElement('footer');
footer.className = 'Card--cardFooter--5QreR';
wrapper.appendChild(footer);

element.parentNode.insertBefore(wrapper, element.nextSibling);
